param([string]$BaseUrl='http://localhost:8080')
$ErrorActionPreference='Stop';function E($a,$b,$n){if($a-ne$b){throw "$n expected=$b actual=$a"}};function I($m,$p,$b=$null,$h=$null){$x=@{Method=$m;Uri="$BaseUrl$p";SkipHttpErrorCheck=$true};if($h){$x.Headers=$h};if($null-ne$b){$x.ContentType='application/json';$x.Body=$b|ConvertTo-Json -Compress};$r=Invoke-WebRequest @x;[pscustomobject]@{s=[int]$r.StatusCode;j=$r.Content|ConvertFrom-Json}}
if(-not$env:MALLU_DB_PASSWORD){throw 'need db password'};& "$PSScriptRoot\reset-test-environment.ps1" -SkipRedisRebuildWait;$old=$env:MYSQL_PWD;try{$env:MYSQL_PWD=$env:MALLU_DB_PASSWORD;$sql=(Resolve-Path "$PSScriptRoot\..\src\main\resources\sql\scenarios\marketing-edge.sql").Path.Replace('\','/');& (Get-Command mysql.exe).Source --protocol=TCP --host=127.0.0.1 --port=3306 --user=root --database=mallu --default-character-set=utf8mb4 -e "SOURCE $sql";if($LASTEXITCODE-ne0){throw 'marketing scenario import failed'}}finally{$env:MYSQL_PWD=$old}
$u="mkt_edge_$(Get-Random -Minimum 100000 -Maximum 999999)";$r=I POST '/api/auth/register' @{username=$u;password='MarketEdge_2026'};$h=@{Authorization="Bearer $($r.j.data.token)"};foreach($id in @(3,4,5,6)){$x=I POST "/api/coupons/$id/claim" $null $h;E $x.s 409 "MKT edge $id";E $x.j.code 4092 "MKT edge code $id"};$direct=I POST '/api/coupons/7/claim' $null $h;E $direct.s 200 'MKT-014 claim';Write-Host 'PASS: marketing availability edge.'
